// Extract the inbound WhatsApp message and resolve the connected business.
// Only ACTIVE, CONNECTED numbers are served (business_whatsapp filters).
const body = $input.first().json.body;
const change = body?.entry?.[0]?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

if (!message || message.type !== 'text') {
  return [];
}

const from = String(message.from || '');
const text = String(message.text?.body || '').trim();
if (!from || !text) return [];

const base = $env.N8N_SUPABASE_URL + '/rest/v1';
const headers = {
  apikey: $env.N8N_SUPABASE_SERVICE_KEY,
  Authorization: 'Bearer ' + $env.N8N_SUPABASE_SERVICE_KEY,
  Accept: 'application/json',
};

const phoneNumberId = String(value?.metadata?.phone_number_id || '');
let businessId = null;
if (phoneNumberId) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/business_whatsapp?phone_number_id=eq.${encodeURIComponent(phoneNumberId)}&is_active=eq.true&status=eq.connected&select=business_id,display_phone_number&limit=1`,
    headers,
    json: true,
  });
  businessId = Array.isArray(resp) && resp.length > 0 ? resp[0].business_id : null;
}

let cart = [];
let step = 'idle';
let lastConfirmedMessageId = null;
if (businessId) {
  const sessionResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/whatsapp_sessions?business_id=eq.${businessId}&chat_id=eq.${encodeURIComponent(from)}&select=state&limit=1`,
    headers,
    json: true,
  });
  const state = sessionResp?.[0]?.state;
  if (state && typeof state === 'object') {
    cart = Array.isArray(state.cart) ? state.cart : [];
    step = state.step || 'idle';
    lastConfirmedMessageId = state.lastConfirmedMessageId || null;
  }
}

const contactName = String(value?.contacts?.[0]?.profile?.name || '');

return [{
  json: {
    from,
    messageId: String(message.id || ''),
    text,
    contactName,
    phoneNumberId,
    displayPhoneNumber: String(value?.metadata?.display_phone_number || ''),
    businessId,
    found: Boolean(businessId),
    cart,
    step,
    lastConfirmedMessageId,
  },
}];

// Core bot logic: intent detection + actions.
// Session mutations use the atomic RPCs (whatsapp_session_add_item /
// whatsapp_session_reset) so concurrent messages can't lose updates.
const c = $input.first().json;
const base = $env.N8N_SUPABASE_URL + '/rest/v1';
const headers = {
  apikey: $env.N8N_SUPABASE_SERVICE_KEY,
  Authorization: 'Bearer ' + $env.N8N_SUPABASE_SERVICE_KEY,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const text = c.text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const has = (...patterns) => patterns.some((p) => text.includes(p));
const isYes = /^(si|sip|ok|okey|dale|confirm|confirmar|listo)$/i.test(c.text.trim());
const isNo = /^(no|nop|cancel|cancelar|borrar|vaciar)$/i.test(c.text.trim());

const money = (cents) => '$' + (cents / 100).toLocaleString('es-AR');
const cart = c.cart || [];

let intent;
if (c.step === 'confirming' && (isYes || has('confirmar pedido'))) intent = 'confirm_order';
else if (c.step === 'confirming' && isNo) intent = 'cancel_cart';
else if (cart.length && isYes) intent = 'confirm_order';
else if (has('hola', 'buenas', 'ayuda', 'help', 'empezar', 'que se puede hacer', 'qué se puede hacer')) intent = 'help';
else if (has('menú', 'menu', 'carta', 'que tienen', 'qué tienen', 'que venden', 'qué venden', 'listado')) intent = 'menu';
else if (has('horario', 'abierto', 'cerrado', 'abren', 'cierran', 'hasta que hora')) intent = 'hours';
else if (has('cancelar', 'borrar', 'vaciar', 'reset')) intent = 'cancel_cart';
else intent = 'add_item';

// Idempotency: Meta may retry the same message; never reply twice to a confirm.
if (c.lastConfirmedMessageId === c.messageId && c.lastConfirmedMessageId) {
  return [{ json: { ...c, reply: 'Tu pedido ya fue enviado ✅' } }];
}

// ----- MENÚ -----
if (intent === 'menu') {
  const prods = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/products?business_id=eq.' + c.businessId + '&available=eq.true&select=name,price_cents&order=sort_order.asc',
    headers,
    json: true,
  });
  if (!prods.length) {
    return [{ json: { ...c, reply: 'Todavía no cargamos la carta 📝. Volvé pronto.' } }];
  }
  const lines = prods.map((p) => '• ' + p.name + ' — ' + money(p.price_cents));
  return [{ json: { ...c, reply: '🪧 Menú:\n' + lines.join('\n') + '\n\nEscribí la cantidad y el plato, ej: "2 muzza".' } }];
}

// ----- HORARIOS (reales desde business_hours) -----
if (intent === 'hours') {
  const days = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/business_hours?business_id=eq.' + c.businessId + '&select=weekday,open_time,close_time,closed&order=weekday.asc',
    headers,
    json: true,
  });
  if (!rows.length) {
    return [{ json: { ...c, reply: 'Aún no configuramos los horarios de este local 🕐.' } }];
  }
  const fmtTime = (t) => (t ? String(t).slice(0, 5) : '--:--');
  const lines = rows.map((r) => {
    const name = days[r.weekday] || ('Día ' + r.weekday);
    return r.closed ? `• ${name}: Cerrado` : `• ${name}: ${fmtTime(r.open_time)} a ${fmtTime(r.close_time)}`;
  });
  return [{ json: { ...c, reply: '🕐 Horarios de atención:\n' + lines.join('\n') } }];
}

// ----- CANCELAR / VACIAR -----
if (intent === 'cancel_cart') {
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/rpc/whatsapp_session_reset',
    headers,
    body: { p_business_id: c.businessId, p_chat_id: c.from, p_step: 'idle', p_cart: [] },
    json: true,
  });
  return [{ json: { ...c, reply: 'Cancelamos el carrito 🗑️. Escribí "menú" para volver a empezar.', cart: [], step: 'idle' } }];
}

// ----- CONFIRMAR PEDIDO -----
if (intent === 'confirm_order') {
  // Idempotency: Meta may retry the same message; never double-create.
  if (c.lastConfirmedMessageId === c.messageId) {
    return [{ json: { ...c, reply: 'Tu pedido ya fue enviado ✅' } }];
  }
  if (!cart.length) {
    return [{ json: { ...c, reply: 'Tu carrito está vacío 🛒. Escribí ej: "2 muzza".' } }];
  }
  const payload = {
    businessId: c.businessId,
    waChatId: c.from,
    customerName: c.contactName || undefined,
    customerPhone: c.from,
    notes: 'Pedido por WhatsApp',
    items: cart.map((i) => ({
      productId: i.productId,
      name: i.name,
      quantity: i.quantity,
      unitPriceCents: i.unitPriceCents,
    })),
  };
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.N8N_APP_URL + '/api/webhooks/whatsapp',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'x-whatsapp-secret': $env.N8N_WHATSAPP_WEBHOOK_SECRET,
    },
    body: payload,
    returnFullResponse: true,
    json: true,
  });
  const ok = resp.statusCode < 300 && resp.body && resp.body.success === true;
  if (ok) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/rpc/whatsapp_session_reset',
      headers,
      body: {
        p_business_id: c.businessId,
        p_chat_id: c.from,
        p_step: 'idle',
        p_cart: [],
        p_last_confirmed_message_id: c.messageId,
      },
      json: true,
    });
    return [{ json: { ...c, reply: '✅ ¡Pedido enviado al local! Número: *' + resp.body.orderId + '*', cart: [], step: 'idle' } }];
  }
  return [{ json: { ...c, reply: '😕 Hubo un problema al registrar tu pedido. Escribí *cancelar* y probá de nuevo.' } }];
}

// ----- AYUDA -----
if (intent === 'help') {
  let cartTxt = '';
  if (cart.length) {
    const sum = cart.reduce((acc, i) => acc + i.quantity * i.unitPriceCents, 0);
    cartTxt = '\n\n📋 Tu carrito:\n' + cart.map((i) => `${i.quantity}x ${i.name} — ${money(i.quantity * i.unitPriceCents)}`).join('\n') + '\nTotal: ' + money(sum) + '\n\nEscribí *confirmar* para enviarlo.';
  }
  const lines = [
    `¡Hola${c.contactName ? ' ' + c.contactName : ''}! 👋`,
    'Soy el bot de este local.',
    '• *menú* — ver la carta',
    '• *horario* — horarios de atención',
    '• Ej: *"2 muzza"* — armar el pedido',
    '• *confirmar* — enviar el pedido',
    '• *cancelar* — vaciar el carrito',
  ];
  return [{ json: { ...c, reply: lines.join('\n') + cartTxt } }];
}

// ----- AGREGAR ITEM (atómico vía RPC) -----
let qty = 1;
let term = text;
const qtyMatch = text.match(/^(\d+)\s+(.+)/);
if (qtyMatch) {
  qty = Math.min(99, Math.max(1, parseInt(qtyMatch[1], 10)));
  term = qtyMatch[2];
} else if (/^un[ao]?\s/.test(text)) {
  term = text.replace(/^un[ao]?\s/, '');
}
if (!term) {
  return [{ json: { ...c, reply: 'Escribí qué querés pedir, ej: *"2 muzza"*.' } }];
}

const prods = await this.helpers.httpRequest({
  method: 'GET',
  url: base + '/products?business_id=eq.' + c.businessId + '&available=eq.true&name=ilike.*' + encodeURIComponent(term) + '*&select=id,name,price_cents&order=sort_order.asc&limit=5',
  headers,
  json: true,
});
if (!prods.length) {
  return [{ json: { ...c, reply: 'No encontramos *"' + term + '"* en la carta 😕. Probá con "menú".' } }];
}

const product = prods[0];
const sessionResp = await this.helpers.httpRequest({
  method: 'POST',
  url: base + '/rpc/whatsapp_session_add_item',
  headers,
  body: {
    p_business_id: c.businessId,
    p_chat_id: c.from,
    p_product: {
      productId: product.id,
      name: product.name,
      quantity: qty,
      unitPriceCents: product.price_cents,
    },
  },
  json: true,
});
const state = sessionResp && typeof sessionResp === 'object' ? sessionResp : { cart, step: 'confirming' };
const newCart = Array.isArray(state.cart) ? state.cart : [];
const sum = newCart.reduce((acc, i) => acc + i.quantity * i.unitPriceCents, 0);
const list = newCart.map((i) => `${i.quantity}x ${i.name} — ${money(i.quantity * i.unitPriceCents)}`).join('\n');

return [{
  json: {
    ...c,
    cart: newCart,
    step: 'confirming',
    reply: `Agregamos *${qty}x ${product.name}* ✅\n\n📋 Carrito:\n${list}\n*Total: ${money(sum)}*\n\n¿Confirmás? Escribí *confirmar* o *cancelar*.`,
  },
}];
